const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define locations
  const chiangMai = ee.Geometry.Point([98.98, 18.79]);
  const bangkok = ee.Geometry.Point([100.50, 13.75]);

  // 2. Define time period
  const startDate = '2024-03-01';
  const endDate = '2024-03-31';

  // 3. Load MODIS AOD data (MCD19A2 - MAIAC product)
  let aodCollection = ee.ImageCollection('MODIS/061/MCD19A2_GRANULES')
    .filterDate(startDate, endDate)
    .select('Optical_Depth_047');

  // Check Chiang Mai
  const cmCollection = aodCollection.filterBounds(chiangMai);
  const cmSize = cmCollection.size().getInfo();
  console.log(`Chiang Mai images: ${cmSize}`);

  // Check Bangkok
  const bkkCollection = aodCollection.filterBounds(bangkok);
  const bkkSize = bkkCollection.size().getInfo();
  console.log(`Bangkok images: ${bkkSize}`);

  // If no data, try alternative MODIS product
  if (cmSize === 0 || bkkSize === 0) {
    console.log('Trying MOD08_D3 daily global product...');
    aodCollection = ee.ImageCollection('MODIS/061/MOD08_D3')
      .filterDate(startDate, endDate)
      .select('AOD_550_Dark_Target_Deep_Blue_Combined_Mean');

    const cmSize2 = aodCollection.size().getInfo();
    console.log(`Alternative product images: ${cmSize2}`);

    if (cmSize2 === 0) {
      console.log('No data available for March 2024');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Calculate mean AOD for both locations
  const cmMosaic = cmCollection.mean();
  const bkkMosaic = bkkCollection.mean();

  // Reduce region for Chiang Mai
  const cmStats = cmMosaic.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: chiangMai.buffer(5000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const cmAOD = cmStats['Optical_Depth_047_mean'] || cmStats['AOD_550_Dark_Target_Deep_Blue_Combined_Mean_mean'];
  const cmCount = cmStats['Optical_Depth_047_count'] || cmStats['AOD_550_Dark_Target_Deep_Blue_Combined_Mean_count'];

  // Reduce region for Bangkok
  const bkkStats = bkkMosaic.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: bangkok.buffer(5000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const bkkAOD = bkkStats['Optical_Depth_047_mean'] || bkkStats['AOD_550_Dark_Target_Deep_Blue_Combined_Mean_mean'];
  const bkkCount = bkkStats['Optical_Depth_047_count'] || bkkStats['AOD_550_Dark_Target_Deep_Blue_Combined_Mean_count'];

  console.log(`Chiang Mai: AOD=${cmAOD}, Pixels=${cmCount}`);
  console.log(`Bangkok: AOD=${bkkAOD}, Pixels=${bkkCount}`);

  // 5. Validation and answer
  if (cmCount === 0 || bkkCount === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  if (cmAOD === null || cmAOD === undefined || bkkAOD === null || bkkAOD === undefined) {
    console.log('Calculation failed - null results');
    console.log('<answer>C3</answer>');
    return;
  }

  if (isNaN(cmAOD) || isNaN(bkkAOD) || cmAOD < 0 || cmAOD > 5 || bkkAOD < 0 || bkkAOD > 5) {
    console.log('Invalid AOD values detected');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare AOD values
  if (cmAOD > bkkAOD) {
    console.log('Chiang Mai AOD higher than Bangkok');
    console.log('<answer>A</answer>');
  } else {
    console.log('Chiang Mai AOD not higher than Bangkok');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
